int prefixSum(int i) { if (i < 0) return 0; int s = 0; for (i++; i > 0; i -= i & (-i)) s += bit[i]; return s; }

long long numberOfPairs(vector<int>& nums1, vector<int>& nums2, int diff) {
    int n = nums1.size();
    vector<int> arr(n);
    for (int k = 0; k < n; k++) arr[k] = nums1[k] - nums2[k];
    int shift = 200000;
    sz = 400001;
    bit.assign(sz + 2, 0);
    long long count = 0;
    for (int j = 0; j < n; j++) {
        int bound = min(arr[j] + diff + shift, sz);
        count += prefixSum(bound);
        update(arr[j] + shift);
    }
    return count;
}
